import { ReactElement } from 'react';
import MuiTableContainer, { TableContainerProps as MuiTableContainerProps } from '@mui/material/TableContainer';
import Paper, { PaperProps } from '@mui/material/Paper';

export interface ListingTableContainerProps extends MuiTableContainerProps {
  /**
   * Elevation level for Paper wrapper
   * @default 1
   */
  elevation?: PaperProps['elevation'];
  /**
   * Remove Paper wrapper and render as plain container
   * @default false
   */
  disablePaper?: boolean;
}

export function ListingTableContainer({
  elevation = 1,
  disablePaper = false,
  children,
  ...props
}: ListingTableContainerProps): ReactElement {
  if (disablePaper) {
    return (
      <MuiTableContainer sx={{ width: '100%', ...props.sx }} {...props}>
        {children}
      </MuiTableContainer>
    );
  }

  return (
    <MuiTableContainer component={Paper} elevation={elevation} sx={{ width: '100%', ...props.sx }} {...props}>
      {children}
    </MuiTableContainer>
  );
}

export default ListingTableContainer;
