import * as React from 'react';
import ListItemText from '@mui/material/ListItemText';
import { styled } from '@mui/material/styles';
import type { SxProps, Theme } from '@mui/material/styles';
import { useSidebar } from './context';
import { useSidebarItemContext } from './SidebarItemContext';

/**
 * Props for the styled component.
 */
interface SidebarItemLabelRootProps {
  ownerState: {
    isActive: boolean
    collapsed: boolean
  }
}

/**
 * Styled label for sidebar items.
 */
const SidebarItemLabelRoot = styled(ListItemText, {
  name: 'MuiSidebar',
  slot: 'ItemLabel',
  shouldForwardProp: prop => prop !== 'ownerState',
})<SidebarItemLabelRootProps>(({ theme, ownerState }) => ({
  margin: 0,
  opacity: ownerState.collapsed ? 0 : 1,
  width: ownerState.collapsed ? 0 : 'auto',
  overflow: 'hidden',
  whiteSpace: 'nowrap',
  transition: theme.transitions.create(['opacity', 'width', 'margin'], {
    easing: theme.transitions.easing.sharp,
    duration: ownerState.collapsed
      ? theme.transitions.duration.leavingScreen
      : theme.transitions.duration.enteringScreen,
  }),
  '& .MuiListItemText-primary': {
    fontSize: 14,
    fontWeight: ownerState.isActive ? 600 : 400,
  },
}));

/**
 * Props for SidebarItemLabel component.
 */
export interface SidebarItemLabelProps {
  /** Label text to display */
  children: React.ReactNode;
  /** Additional sx props */
  sx?: SxProps<Theme>;
}

/**
 * SidebarItemLabel - Label text for a sidebar item.
 *
 * Automatically hidden when sidebar is collapsed. Adjusts font weight
 * based on active state.
 *
 * @example
 * ```tsx
 * <Sidebar.Item id="home">
 *   <Sidebar.ItemIcon><Home size={20} /></Sidebar.ItemIcon>
 *   <Sidebar.ItemLabel>Home</Sidebar.ItemLabel>
 * </Sidebar.Item>
 * ```
 */
export const SidebarItemLabel: React.FC<SidebarItemLabelProps> = ({
  children,
  sx,
}) => {
  const { collapsed } = useSidebar();
  const { isActive } = useSidebarItemContext();

  return <SidebarItemLabelRoot primary={children} ownerState={{ isActive, collapsed }} sx={sx} />
}

// Add display name for child detection
SidebarItemLabel.displayName = 'SidebarItemLabel';

export default SidebarItemLabel;
