import * as React from 'react';
import Box from '@mui/material/Box';
import { styled } from '@mui/material/styles';
import type { SxProps, Theme } from '@mui/material/styles';

/**
 * Styled container for header actions.
 */
const HeaderActionsRoot = styled(Box, {
  name: 'MuiHeader',
  slot: 'Actions',
})(({ theme }) => ({
  display: 'flex',
  alignItems: 'center',
  gap: theme.spacing(0.5),
}));

/**
 * Props for HeaderActions component.
 */
export interface HeaderActionsProps {
  /** Action elements (theme toggle, notifications, user menu, etc.) */
  children: React.ReactNode;
  /** Additional sx props */
  sx?: SxProps<Theme>;
}

/**
 * HeaderActions - Container for action buttons in the header.
 *
 * Provides a flex container for right-aligned actions like theme toggle,
 * notifications, help, and user menu.
 *
 * Typical children:
 * - ColorSchemeToggle
 * - HelpButton
 * - NotificationButton
 * - UserMenu
 */
export const HeaderActions: React.FC<HeaderActionsProps> = ({
  children,
  sx,
}) => {
  return <HeaderActionsRoot sx={sx}>{children}</HeaderActionsRoot>;
};

export default HeaderActions;
