import { ReactNode } from 'react';
import MuiListItemText, { ListItemTextProps } from '@mui/material/ListItemText';

export interface ComplexSelectMenuItemTextProps extends ListItemTextProps {
  primary: ReactNode;
  secondary?: ReactNode;
}

export function ComplexSelectMenuItemText({ primary, secondary, ...props }: ComplexSelectMenuItemTextProps) {
  return (
    <MuiListItemText 
      primary={primary} 
      secondary={secondary} 
      slotProps={{ secondary: { variant: 'caption' } }}
      {...props} 
    />
  );
}

ComplexSelectMenuItemText.displayName = 'ComplexSelect.MenuItemText';

export default ComplexSelectMenuItemText;
